def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    prerelease = ''.chr((ord("a") - 97 + j) % 26 + 97)*j for j in range(1, min(n, 4)+1))
    version = ".".join(chunks) + "-" + prerelease
